INSERT INTO `temas` (`id`, `tema`, `slogan`, `detalle`, `indice`, `materia_id`, `created_at`, `updated_at`) VALUES (1,'Potenciación','Potencia tus habilidades matemáticas.','<p>Multiplicación abreviada de un número por sí mismo (base elevado a un exponente). Fundamental en diversas áreas.</p>',0,1,'2023-04-17 05:24:39','2025-05-02 07:37:56'),(2,'Radicación','Descubre las propiedades de los radicales que te permiten resolver ejercicios','<p>Operación inversa a la potenciación. Busca la base que, elevada a una potencia, da un resultado.</p>',0,1,'2023-04-17 05:24:39','2025-05-31 19:19:58'),(3,'Ecuación Cuadrática','Resuelve ecuaciones de segundo grado fácilmente.','<p>Ecuaciones algebraicas donde la variable tiene exponente dos. Su gráfica es una parábola.</p>',0,1,'2023-04-17 05:24:39','2025-05-02 07:52:08'),(4,'MOVIMIENTO RECTILINEO UNIFORME MRU','MRU: Velocidad constante en línea recta.','Movimiento con velocidad constante y trayectoria rectilínea. No presenta aceleración.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(5,'MOVIMIENTO RECTILINEO UNIFORMEMENTE VARIADO MRUV','MRUV: Aceleración constante en línea recta.','Movimiento con trayectoria rectilínea y aceleración constante. La velocidad varía uniformemente.',2,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(6,'LOGARITMOS','Logaritmos: La herramienta para exponentes.','<p>Función matemática que encuentra el exponente al que debe elevarse una base para obtener un número.</p>',0,1,'2023-04-17 05:24:39','2025-05-02 07:53:00'),(7,'INTRODUCCION A LA GEOMETRIA ANALITICA','Geometría y álgebra unidas.','Uso de un sistema de coordenadas para el estudio de figuras geométricas mediante álgebra.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(8,'PROGRESIONES ARITMETICAS','Descubre el patrón en las secuencias.','<p>Sucesiones numéricas con reglas definidas para obtener cada término a partir de los anteriores.</p>',0,1,'2023-04-17 05:24:39','2025-05-31 16:39:46'),(9,'LOGICA SIMBOLICA','Desarrolla tu pensamiento lógico.','Sistema formal que analiza la validez de argumentos mediante símbolos y reglas.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(10,'DESIGUALDADES Y VALOR ABSOLUTO','Comprende las relaciones de orden y la magnitud.','Estudio de expresiones con signos >, <, ≥, ≤ y la distancia de un número al cero.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(11,'RAZONES TRIGONOMETRICAS','Explora las relaciones entre los ángulos de un triángulo.','Funciones que relacionan los ángulos de un triángulo rectángulo con las proporciones de sus lados.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(12,'TRIANGULOS RECTANGULOS','El triángulo con un ángulo recto.','Triángulos que contienen un ángulo de 90 grados. Importancia del teorema de Pitágoras.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(13,'IDENTIDADES','Simplifica expresiones algebraicas y trigonométricas.','Igualdades que se cumplen para todos los valores de las variables involucradas.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(14,'SISTEMA DE ECUACIONES LINEALES','Resuelve conjuntos de ecuaciones con múltiples incógnitas.','Conjunto de dos o más ecuaciones lineales que comparten las mismas variables.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(15,'CONJUNTOS','La base de la organización matemática.','Agrupaciones de elementos con características definidas.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(16,'FUNCIONES','Relaciones con una salida única para cada entrada.','Regla de correspondencia entre dos conjuntos donde cada elemento del primer conjunto se relaciona con uno y solo un elemento del segundo.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(17,'RELACIONES','Vinculando elementos entre conjuntos.','Subconjuntos del producto cartesiano entre dos o más conjuntos.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(18,'LA RECTA','El camino más corto entre dos puntos.','Objeto geométrico unidimensional definido por dos puntos o una pendiente y un punto.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(19,'LA CIRCUNFERENCIA','Una curva cerrada con distancia constante al centro.','<p>Conjunto de puntos equidistantes de un punto fijo llamado centro.</p>',0,1,'2023-04-17 05:24:39','2025-09-12 03:48:43'),(20,'LA PARABOLA','Una curva con un punto fijo y una línea directriz.','Lugar geométrico de los puntos que equidistan de un foco y una directriz.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(21,'LA ELIPSE','Una curva con dos focos.','Lugar geométrico de los puntos cuya suma de distancias a dos focos es constante.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(22,'LA HIPERBOLA','Una curva con dos ramas.','Lugar geométrico de los puntos cuya diferencia de distancias a dos focos es constante.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(23,'LIMITES','Acercándonos a un valor sin alcanzarlo.','Concepto fundamental del cálculo que describe el valor al que se aproxima una función.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(24,'DERIVADAS','La razón de cambio instantánea.','Medida de cómo cambia una función con respecto a su variable.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(25,'INTEGRALES','Encontrando el área bajo la curva.','Concepto del cálculo para determinar el área delimitada por una función.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(26,'DESCOMPOSICION FACTORIAL (casos de factorización)','Expresando números y polinomios como productos.','<p>Proceso de escribir un número o polinomio como la multiplicación de sus factores.</p>',0,1,'2023-04-17 05:24:39','2025-08-01 02:31:58'),(28,'AREAS DE FIGURAS PLANAS Y CUERPOS GEOMETRICOS','Calculando superficies bidimensionales.','<p>Medida de la superficie delimitada por el contorno de una figura geométrica plana y algunos cuerpos geométricos</p>',0,1,'2023-04-17 05:24:39','2025-05-20 22:15:51'),(29,'VOLUMENES DE CUERPOS','Midiendo el espacio tridimensional.','Cantidad de espacio que ocupa un cuerpo geométrico tridimensional.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(31,'TRIANGULOS OBLICUANGULOS','Triángulos sin ángulos rectos.','Triángulos que no contienen ningún ángulo de 90 grados.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(32,'RELACION INVERSA Y DIRECTAMENTE PROPORCIONALES','Entendiendo cómo varían las cantidades juntas.','Estudio de cómo dos magnitudes se relacionan cuando una aumenta o disminuye.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(33,'REGLA DE 3 SIMPLE Y COMPUESTA','Resolviendo problemas de proporcionalidad.','Método para encontrar un valor desconocido en problemas de proporcionalidad directa o inversa.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(34,'CLASIFICACION DE LOS TRIANGULOS SEGUN SUS LADOS','Identificando triángulos por la longitud de sus lados.','Categorización de triángulos en equiláteros, isósceles y escalenos.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(35,'CLASIFICACION DE LOS TRIANGULOS SEGUN SUS ANGULOS','Identificando triángulos por la medida de sus ángulos.','Categorización de triángulos en acutángulos, rectángulos y obtusángulos.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(36,'PERIMETROS DE FIGURAS PLANAS','Calculando el contorno de figuras geométricas.','<p>Suma de las longitudes de los lados de un polígono.</p>',0,1,'2023-04-17 05:24:39','2025-05-21 02:47:07'),(37,'AREA DE POLIGONOS POR COORDENADAS','Calculando áreas usando puntos en el plano.','Método para hallar el área de un polígono utilizando las coordenadas de sus vértices.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(38,'CONVERSION DE FRACCIONES DECIMALES A FRACCIONES COMUNES','Transformando números con decimales a fracciones.','Proceso para expresar un número decimal como una fracción irreducible.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(39,'NOTACIÓN CIENTIFICA','Expresando números grandes o pequeños de forma concisa.','Manera de escribir números utilizando potencias de diez.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(40,'PRODUCTOS NOTABLES','Patrones algebraicos para una multiplicación rápida.','Fórmulas para obtener el resultado de ciertas multiplicaciones de polinomios de forma directa.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(41,'COCIENTES NOTABLES','Patrones algebraicos para una división rápida.','Fórmulas para obtener el resultado de ciertas divisiones de polinomios de forma directa.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(42,'BINOMIO DE NEWTON POR EL TRIANGULO DE PASCAL Y POR COMBINATORIA','Expandiendo binomios a cualquier potencia.','<p>Métodos para desarrollar la potencia de un binomio utilizando el triángulo de Pascal o combinatoria.</p>',0,1,'2023-04-17 05:24:39','2025-07-05 03:14:27'),(43,'FACTORIAL,COMBINACION, PERMUTACION Y VARIACION','Contando y ordenando elementos.','Técnicas de conteo para determinar el número de arreglos posibles de un conjunto de elementos.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(44,'INDUCCION COMPLETA','Demostrando proposiciones para infinitos casos.','Método de demostración matemática para probar la validez de una afirmación para todos los números naturales.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(45,'NUMEROS COMPLEJOS','Explorando una dimensión numérica más allá de los reales.','<p>Extensión de los números reales que incluye la unidad imaginaria \'i\', donde $i^2 = -1$.</p>',0,1,'2023-04-17 05:24:39','2025-06-24 02:35:46'),(46,'MULTIPLICADORES DE LAGRANGE','Optimizando funciones con restricciones.','Método para encontrar los máximos y mínimos de una función sujeta a una o más restricciones.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(47,'GRAFICA DE FUNCIONES TRIGONOMETRICAS','Visualizando las ondas matemáticas.','Representación gráfica de las funciones seno, coseno, tangente, cotangente, secante y cosecante.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(48,'CRITERIOS DE DIVISIBILIDAD','Identificando divisores sin realizar la división.','Reglas que permiten determinar si un número entero es divisible por otro sin efectuar la operación.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(49,'RAIZ CUADRADA Y RAIZ CUBICA','Encontrando el número que multiplicado por sí mismo da otro.','Operaciones de radicación con índice 2 y 3 respectivamente.',1,1,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(50,'NOTACION CIENTIFICA','Simplificando la expresión de cantidades extremas.','Forma de escribir números muy grandes o muy pequeños como un producto de un número entre 1 y 10 y una potencia de 10.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(51,'ESCALA TERMICA','Midiendo la temperatura.','Sistemas de referencia para cuantificar el grado de calor de un cuerpo (Celsius, Fahrenheit, Kelvin).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(52,'DILATACION TERMICA','Cómo los materiales cambian con la temperatura.','Aumento o disminución del volumen de un material debido a cambios en su temperatura.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(53,'CALORIMETRIA','Midiendo el flujo de calor.','Rama de la física que estudia la medición de las cantidades de calor intercambiadas en procesos físicos y químicos.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(54,'LEY DE LOS GASES','Comportamiento de la materia en estado gaseoso.','Conjunto de leyes físicas que describen el comportamiento de los gases ideales (Boyle, Charles, Gay-Lussac, Avogadro).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(55,'MOVIMIENTO RECTILINEO UNIFORMEMENTE VARIADO','Aceleración constante en línea recta.','Estudio del movimiento donde la velocidad cambia de manera uniforme con el tiempo.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(56,'MOVIMIENTO VERTICAL- CAIDA LIBRE','El movimiento bajo la influencia de la gravedad.','Caso especial del MRUV donde la aceleración es la de la gravedad.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(57,'MOVIMIENTO PARABOLICO','La trayectoria curva de un proyectil.','Movimiento en dos dimensiones bajo la acción de la gravedad.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(58,'MOVIMIENTO CIRCULAR UNIFORME','Velocidad angular constante en una trayectoria circular.','Movimiento donde un objeto se desplaza a velocidad constante alrededor de un eje de rotación.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(59,'MOVIMIENTO CIRCULAR UNIFORMEMENTE VARIADO','Aceleración angular constante en una trayectoria circular.','Movimiento circular donde la velocidad angular cambia de manera uniforme con el tiempo.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(60,'MOVIMIENTO OSCILATORIO','El vaivén repetitivo.','Movimiento periódico alrededor de una posición de equilibrio.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(61,'DINAMICA DE PARTICULAS','La física de las fuerzas y el movimiento.','Rama de la mecánica que estudia las causas del movimiento de las partículas (fuerzas).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(62,'FUERZA ELECTRICA','La interacción entre cargas.','Fuerza de atracción o repulsión entre objetos con carga eléctrica (Ley de Coulomb).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(63,'CAMPO ELECTRICO','La influencia invisible de la carga.','Región del espacio donde una carga eléctrica experimenta una fuerza.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(64,'POTENCIAL ELECTRICO','La energía potencial por unidad de carga.','Trabajo necesario para mover una carga unitaria desde un punto de referencia hasta un punto en el campo eléctrico.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(65,'TRABAJO ELECTRICO','Energía transferida por fuerzas eléctricas.','Trabajo realizado por el campo eléctrico al mover una carga entre dos puntos.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(66,'CAPACIDAD ELECTRICA','La habilidad para almacenar carga.','Medida de la cantidad de carga eléctrica que un conductor puede almacenar para un potencial dado.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(67,'ASOCIACION DE CONDENSADORES','Combinando la capacidad de almacenamiento.','Formas de conectar capacitores en serie y paralelo para obtener una capacitancia equivalente.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(68,'CIRCUITOS ELECTRICOS','El camino para la corriente.','Trayectoria cerrada que permite el flujo de corriente eléctrica.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(69,'LEYES DE KIRCHHOFF','Analizando el flujo de corriente y voltaje en circuitos.','Conjunto de dos leyes fundamentales para el análisis de circuitos eléctricos (ley de nodos y ley de mallas).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(70,'LEYES DE KEPLER','Describiendo el movimiento planetario.','Tres leyes que describen el movimiento de los planetas alrededor del Sol.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(71,'OPTICA','La ciencia de la luz y la visión.','Rama de la física que estudia el comportamiento y las propiedades de la luz.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(73,'ELECTROMAGNETISMO','La fuerza que une electricidad y magnetismo.','Rama de la física que estudia la interacción entre los campos eléctrico y magnético.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(74,'EQUILIBRIO TERMICO','Cuando las temperaturas se igualan.','Estado en el que dos o más sistemas en contacto térmico dejan de intercambiar calor.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(75,'CAMBIOS DE ESTADO','Las transformaciones de la materia.','Transiciones entre los estados sólido, líquido y gaseoso (fusión, vaporización, sublimación, etc.).',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(76,'TEORIA DE ERRORES','Cuantificando la incertidumbre en las mediciones.','Estudio de las desviaciones entre el valor medido y el valor real de una magnitud.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(77,'CENTROS DE GRAVEDAD Y MOMENTOS DE INERCIA','El equilibrio y la resistencia a la rotación.','Punto donde se concentra la masa de un objeto y medida de su resistencia a cambiar su movimiento rotacional.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(78,'PRINCIO DE ARQUIMEDES','La fuerza ascendente en los fluidos.','Un cuerpo sumergido en un fluido experimenta una fuerza de empuje igual al peso del fluido desplazado.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(79,'PRICIPIO DE PASCAL','La presión se transmite en los fluidos.','Un cambio de presión aplicado a un fluido incompresible confinado se transmite íntegramente a todos los puntos del fluido.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(80,'EMPUJES Y FLOTACION','¿Por qué algunos objetos flotan?','Estudio de la fuerza ascendente que ejerce un fluido sobre un objeto sumergido y las condiciones para que flote.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(81,'ECUACION DE CONTINUDAD','El flujo constante en fluidos incompresibles.','En un fluido incompresible, el producto del área de la sección transversal y la velocidad del fluido es constante a lo largo de un tubo de corriente.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(82,'ECUACION DE BERNOULLI','Relacionando presión, velocidad y altura en fluidos.','Describe el comportamiento de un fluido en movimiento, relacionando su presión, velocidad y altura.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(83,'LEY DE LA CONSERVACION DE LA ENERGIA','La energía no se crea ni se destruye, solo se transforma.','Principio fundamental de la física que establece que la energía total de un sistema aislado permanece constante.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(84,'LEY DE LA CONSERVACION DE LA CANTIDAD DE MOVIMIENTO','El momento total de un sistema aislado permanece constante.','Principio físico que establece que la cantidad de movimiento total de un sistema cerrado no cambia si no actúan fuerzas externas sobre él.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(85,'TRABAJO,ENERGIA Y POTENCIA','Los pilares de la mecánica.','Conceptos fundamentales que describen la transferencia de energía, la capacidad de realizar trabajo y la rapidez con la que se realiza el trabajo.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(86,'CORRIENTE ELECTRICA','El flujo de carga eléctrica.','Movimiento ordenado de cargas eléctricas a través de un conductor.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(87,'VECTORES','Magnitud y dirección en el espacio.','Entidades matemáticas que tienen magnitud y dirección, utilizadas para representar magnitudes físicas como fuerza y velocidad.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(88,'GRAVITACION UNIVERSAL','La fuerza que atrae a la materia.','Ley física que describe la fuerza de atracción entre objetos con masa.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(89,'LEYES DE TERMODINAMICA','Los principios que rigen la energía térmica.','Conjunto de leyes fundamentales que describen el comportamiento de la energía térmica y el trabajo.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(90,'ECUACIONES DIMENSIONALES','Analizando las unidades de las magnitudes físicas.','Expresiones algebraicas que muestran las dimensiones de una magnitud física en términos de las unidades fundamentales.',1,2,'2023-04-17 05:24:39','2023-04-17 05:24:39'),(91,'PROGRESIONES GEOMETRICAS','Multiplicando para avanzar en la secuencia.','Secuencia numérica donde cada término se obtiene multiplicando el anterior por una razón constante.',0,1,'2023-04-07 00:40:54','2023-04-07 00:40:54'),(92,'GASES IDEALES','La materia que se expande.','<p>Estado de la materia sin forma ni volumen definidos, cuyas partículas se mueven libremente.</p>',0,3,'2023-04-07 01:55:31','2025-06-03 03:25:25'),(95,'QUIMICA INORGANICA','El estudio de los compuestos sin carbono.','<p>Rama de la química que estudia las sustancias que no contienen enlaces carbono-hidrógeno.</p>',0,3,'2023-08-02 02:10:36','2025-06-03 03:25:43'),(97,'QUIMICA ORGÁNICA','La química de los compuestos del carbono.','<p>Rama de la química que estudia los compuestos que contienen carbono, principalmente con enlaces carbono-hidrógeno.</p>',0,3,'2023-08-03 23:02:36','2025-06-03 03:26:30'),(98,'SOLUCIONES O DISOLUCIONES','Mezclas homogéneas a nivel molecular.','<p>Mezclas uniformes de dos o más sustancias.</p>',0,3,'2023-08-05 23:31:51','2025-06-03 03:26:51'),(99,'EQUILIBRIO QUIMICO DE LAS REACCIONES','El balance en las reacciones químicas.','<p>Estado en el que las velocidades de la reacción directa e inversa son iguales.</p>',0,3,'2023-08-10 20:18:46','2025-06-03 03:27:22'),(100,'Interés Simple','Intereses calculados solo sobre el capital inicial.','Intereses que no se suman al capital para generar nuevos intereses.',0,1,'2023-09-06 20:08:21','2023-09-06 20:08:21'),(101,'Interes Compuesto','Los intereses generan nuevos intereses.','Intereses que se añaden al capital inicial, generando intereses en períodos futuros.',0,1,'2023-09-06 23:52:32','2023-09-06 23:52:32'),(102,'Tabla de frecuencia','Hacer con formulss','<p>Enseñar a paso a paso</p>',0,1,'2025-05-26 20:00:49','2025-05-26 20:00:49'),(103,'TERMODINAMICA','Estudio del calor y temperatura','<p>Estudio del calor y su propagación, leyes termodinámicas y constantes</p>',0,3,'2025-06-03 03:25:02','2025-06-03 03:25:02'),(104,'FORMULAS CON ANGULOS','Cómo identificar los ángulos según su valor','<p>Tipos de angulos de acuerdo al valor</p>',0,1,'2025-06-26 18:34:50','2025-11-19 23:43:35'),(105,'ESTEQUIOMETRÍA','Estudio de las relaciones de masa entre reactivos y productos','<p>Conceptos, constantes y relaciones entre reacciones quimicas</p>',0,3,'2025-07-08 03:25:24','2025-07-08 03:25:24'),(106,'ESTRUCTURA ATOMICA','Cómo están conformados los átomos','<p>Características de niveles y subniveles atómicos</p>',0,3,'2025-08-23 01:20:37','2025-08-23 01:20:37'),(107,'DENSIDADES','Relación entre masa y volumen de las sustancias','<p>Diferentes unidades de densidad</p>',0,3,'2025-08-25 22:37:10','2025-08-25 22:37:10'),(108,'GEOMETRIA ANALITICA EN EL ESPACIO','Cómo son las ecuaciones de conicas en el espacio','<p>Ecuaciones del plano, paraboloide, elipsoide e hiperboloide</p>',0,1,'2025-08-28 23:47:49','2025-08-28 23:47:49');
